use realm_agent::{model::*,task::TaskEngine};
use std::collections::BTreeSet;
fn world(class:u8)->WorldView{
 let p=Position{map:1,x:1232.41,y:-4411.27,z:22.9853,orientation:0.};
 let me=Entity{guid:10,kind:Kind::Player,entry:0,name:Some("Fixture".into()),position:Some(p),health:Some(100),max_health:Some(100),mana:Some(100),max_mana:Some(100),level:Some(60),class:Some(class),rage:None,flags:0,auras:BTreeSet::new(),target:None,updated_ms:0};
 let mut w=WorldView{connected:true,class,self_guid:10,character:"Fixture".into(),position:Some(p),..Default::default()};w.objects.insert(10,me);w
}
fn spec()->TaskSpec{serde_json::from_str(include_str!("../config/task-horde.example.json")).unwrap()}
fn advance(e:&mut TaskEngine,w:&mut WorldView){w.now_ms+=1000;e.tick(w);}
#[test]fn rejects_unready_and_unknown_class(){let mut e=TaskEngine::default();let mut w=world(5);assert!(e.command(Command::Start(spec()),&w).is_err());w.class=8;w.connected=false;assert!(e.command(Command::Start(spec()),&w).is_err());}
#[test]fn warrior_needs_inn_and_navigation_failure_blocks(){let mut e=TaskEngine::default();let mut w=world(1);e.command(Command::Start(spec()),&w).unwrap();advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"travelling_inn");w.now_ms+=1000;assert!(matches!(e.tick(&w).actions.first(),Some(Action::Navigate(_))));e.event(GameEvent::NavigationFailed{reason:"no_path".into()},&w);assert_eq!(e.status().unwrap().phase,"blocked");}
#[test]fn mage_conjure_waits_for_inventory_confirmation(){let mut e=TaskEngine::default();let mut w=world(8);w.spells.insert(10145);w.spells.insert(10140);e.command(Command::Start(spec()),&w).unwrap();advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"conjuring");w.now_ms+=1000;assert!(e.tick(&w).actions.iter().any(|a|matches!(a,Action::Cast{spell:10145,..})));assert_eq!(e.status().unwrap().phase,"conjuring");w.inventory.push(InventoryItem{guid:1,entry:8076,count:20,bag:255,slot:23});w.inventory.push(InventoryItem{guid:2,entry:8079,count:20,bag:255,slot:24});w.now_ms+=6000;e.tick(&w);assert_eq!(e.status().unwrap().phase,"travelling_arena");}
#[test]fn duel_and_recovery_loop_are_observed_not_assumed(){let mut e=TaskEngine::default();let mut w=world(1);let mut s=spec();s.opponents=vec![20];w.inventory.push(InventoryItem{guid:1,entry:8952,count:20,bag:255,slot:23});let mut peer=w.me().unwrap().clone();peer.guid=20;w.objects.insert(20,peer);e.command(Command::Start(s),&w).unwrap();for _ in 0..5{advance(&mut e,&mut w);}assert_eq!(e.status().unwrap().phase,"challenging");w.now_ms+=1000;let effect=e.tick(&w);assert!(effect.actions.iter().any(|a|matches!(a,Action::Cast{spell:7266,..})));e.event(GameEvent::DuelRequested{arbiter:100,challenger:10},&w);e.event(GameEvent::DuelCountdown{seconds:3},&w);advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"countdown");for _ in 0..3{advance(&mut e,&mut w);}assert_eq!(e.status().unwrap().phase,"duelling");e.event(GameEvent::DuelComplete{started:true},&w);assert_eq!(e.status().unwrap().phase,"recovering");advance(&mut e,&mut w);assert_eq!(e.status().unwrap().phase,"checking_supplies");assert_eq!(e.status().unwrap().duels,1);}
#[test]fn no_allowlist_never_challenges_and_pause_stops(){let mut e=TaskEngine::default();let mut w=world(1);w.inventory.push(InventoryItem{guid:1,entry:8952,count:20,bag:255,slot:23});e.command(Command::Start(spec()),&w).unwrap();for _ in 0..8{w.now_ms+=1000;assert!(!e.tick(&w).actions.iter().any(|a|matches!(a,Action::Cast{spell:7266,..})));}let result=e.command(Command::Pause,&w).unwrap();assert!(result.actions.iter().any(|a|matches!(a,Action::StopMoving)));assert!(e.tick(&w).actions.is_empty());}
